	if (!booth_conf)
		return -1;


	input = (type == ARBITRATOR)
		? booth_conf->arb_user
		: booth_conf->site_user;
	if (!*input)
		goto u_inval;
	if (isdigit(input[0])) {
		booth_conf->uid = strtol(input, &cp, 0);
