                break;
            }
            node_identifier = format_nid(value);
            endpoint_identifier = EXTRACT_32BITS(value + 4);
            ND_PRINT((ndo, " NID: %s EPID: %08x",
                node_identifier,
                endpoint_identifier
            ));
        }
            break;

        case DNCP_NETWORK_STATE: {
            uint64_t hash;
            if (bodylen != 8) {
                ND_PRINT((ndo, " %s", istr));
                break;
