        }
            break;

        case DNCP_TRUST_VERDICT: {
            if (bodylen <= 36) {
                ND_PRINT((ndo, " %s", istr));
                break;
            }
            ND_PRINT((ndo, " Verdict: %u Fingerprint: %s Common Name: ",
                *value,
                format_256(value + 4)));
            safeputs(ndo, value + 36, bodylen - 36);
