                ND_PRINT((ndo, "DNS domain: "));
                print_dns_label(ndo, value+1, bodylen-1, 1);
            } else if (policy == 130) {
                ND_PRINT((ndo, "Opaque UTF-8: "));
                safeputs(ndo, value + 1, bodylen - 1);
            } else if (policy == 131) {
                if (bodylen != 1) {
                    ND_PRINT((ndo, " %s", istr));
                    break;
                }
