                ND_PRINT((ndo, " %s", istr));
                break;
            }
            endpoint_identifier = EXTRACT_32BITS(value);
            ip_address = format_ip6addr(ndo, value + 4);
            ND_PRINT((ndo, " EPID: %08x IP Address: %s",
                endpoint_identifier,
                ip_address
            ));

