                ND_PRINT((ndo, " %s", istr));
                break;
            }
            len += 17;
            len += -len & 3;
            if (bodylen >= len)
                hncp_print_rec(ndo, value+len, bodylen-len, indent+1);
        }
            break;

        case HNCP_DOMAIN_NAME: {
            if (bodylen == 0) {
                ND_PRINT((ndo, " %s", istr));
                break;
            }
            ND_PRINT((ndo, " Domain: "));
            print_dns_label(ndo, value, bodylen, 1);
        }
            break;

        case HNCP_NODE_NAME: {
            u_int l;
            if (bodylen < 17) {
                ND_PRINT((ndo, " %s", istr));
                break;
            }
            l = value[16];
            if (bodylen < 17 + l) {
                ND_PRINT((ndo, " %s", istr));
                break;
            }
            ND_PRINT((ndo, " IP-Address: %s Name: ",
                format_ip6addr(ndo, value)
            ));
            if (l < 64) {
                safeputchar(ndo, '"');
                safeputs(ndo, value + 17, l);
                safeputchar(ndo, '"');
