      if (ctx->subj_hash && ctx->hdrs[i]->env->real_subj)
        mutt_hash_delete(ctx->subj_hash, ctx->hdrs[i]->env->real_subj, ctx->hdrs[i]);
      if (ctx->id_hash && ctx->hdrs[i]->env->message_id)
