        {
            hFile = stdin;
            (*hIni)->iniFileType    = 0; /* stdin is always text */
        }
        else
        {
            if ( (*hIni)->iniFileType == 0 )
                hFile = uo_fopen( pszFileName, "r" );
            else
                hFile = (FILE *)iniOS2Open( pszFileName);
        }

