        {
            /*
             * This could fail because of something other than the file not existing...
             */

            if ( bCreate == TRUE )
            {
                if ( (*hIni)->iniFileType == 0 )
                    hFile = uo_fopen( pszFileName, "w+" );
                else
                    hFile = (FILE *)iniOS2Open( pszFileName);
