            c = getc(IN);

            if (c) {
                c1 = getc(IN);

                for (i = 0; i < c && x < W && pix < beyond; i++, x++, pix++) {
                    *pix = (unsigned char)c1;
                }
            } else {
                c = getc(IN);

                if (c == 0x00) { /* EOL */
                    x = 0;
                    ++y;
                    pix = RGB + x + (H - y - 1) * W;
                } else if (c == 0x01) { /* EOP */
                    break;
                } else if (c == 0x02) { /* MOVE by dxdy */
                    c = getc(IN);
                    x += c;
                    c = getc(IN);
                    y += c;
                    pix = RGB + (H - y - 1) * W + x;
                } else { /* 03 .. 255 */
                    i = 0;
                    for (; i < c && x < W && pix < beyond; i++, x++, pix++) {
                        c1 = getc(IN);
                        *pix = (unsigned char)c1;
                    }
                    if (c & 1) { /* skip padding byte */
                        getc(IN);
                    }
                }
            }
        }/* while() */

        if (gray_scale) {
            gray = image->comps[0].data;
            pix = RGB;
            max = W * H;

            while (max--) {
                uc = *pix++;

                *gray++ = table_R[uc];
            }
        } else {
            /*int *red, *green, *blue;*/

            red = image->comps[0].data;
            green = image->comps[1].data;
            blue = image->comps[2].data;
            pix = RGB;
            max = W * H;

            while (max--) {
                uc = *pix++;

                *red++ = table_R[uc];
                *green++ = table_G[uc];
                *blue++ = table_B[uc];
            }
        }
        free(RGB);
        free(table_R);
        free(table_G);
        free(table_B);
    }/* RLE8 */
    else {
        fprintf(stderr,
                "Other system than 24 bits/pixels or 8 bits (no RLE coding) "
                "is not yet implemented [%d]\n", Info_h.biBitCount);
    }
    fclose(IN);
    return image;
}

